package au.aumanet.app;
import java.io.*;import java.net.*;import java.security.*;import java.util.*;import java.util.concurrent.atomic.*;import java.util.function.*;
/** One bounded authenticated target. No activation or start command is replayed. */
final class NodeUpdateTransport implements AutoCloseable {
 interface Signer{byte[] sign(NodeUpdateCodec.Message message)throws Exception;default boolean permitted(NodeUpdateCodec.Message message){return true;}}interface SocketFactory{DatagramSocket open()throws Exception;}
 static final class Reading{final NodeUpdateCodec.Message message;final long started;Reading(NodeUpdateCodec.Message m,long s){message=m;started=s;}boolean fresh(long now){return now>=started&&now-started<NodeUpdateCodec.NONCE_MS;}}
 final GatewayBindingConfig.Node node;final String group,owner,relay;final long epoch;private final SocketFactory factory;private final Signer signer;private final LongSupplier clock;private final BooleanSupplier current;private final AtomicReference<DatagramSocket> socket=new AtomicReference<>();private final AtomicBoolean closed=new AtomicBoolean();
 NodeUpdateTransport(GatewayBindingConfig.Node node,String group,long epoch,String owner,String relay,SocketFactory factory,Signer signer,LongSupplier clock,BooleanSupplier current){this.node=node;this.group=group;this.epoch=epoch;this.owner=owner;this.relay=relay;this.factory=factory;this.signer=signer;this.clock=clock;this.current=current;}
 private boolean live(){return !closed.get()&&current.getAsBoolean();}private void check()throws IOException{if(!live())throw new IOException("Node update stopped");}
 private DatagramSocket socket()throws Exception{check();DatagramSocket existing=socket.get();if(existing!=null&&!existing.isClosed())return existing;DatagramSocket made=factory.open();if(!socket.compareAndSet(existing,made)){made.close();throw new IOException();}if(!live()){socket.compareAndSet(made,null);made.close();throw new IOException();}made.setSoTimeout(200);return made;}
 Reading query(String expectedRun)throws Exception{return exchange(NodeUpdateCodec.query(node.id,group,epoch,owner,relay,GroupWire.random(32).toUpperCase(Locale.ROOT)),null,expectedRun);}
 Reading exchange(NodeUpdateCodec.Message message,Reading reservation,String expectedRun)throws Exception{check();if(!signer.permitted(message))throw new SecurityException();long began=clock.getAsLong();if(reservation!=null&&!reservation.fresh(began))throw new IOException("Node challenge expired");byte[] signed=signer.sign(message);check();long sent=clock.getAsLong();if(sent<began||sent-began>=NodeUpdateCodec.NONCE_MS||reservation!=null&&!reservation.fresh(sent))throw new IOException("Node challenge expired");DatagramSocket selected=socket();byte[] packet=NodeUpdateCodec.envelope(message,signed);check();if(!signer.permitted(message))throw new SecurityException();selected.send(new DatagramPacket(packet,packet.length));int frames=0;while(live()&&clock.getAsLong()>=began&&clock.getAsLong()-began<8000){byte[] bytes=new byte[NodeUpdateCodec.MAX_PACKET+1];DatagramPacket reply=new DatagramPacket(bytes,bytes.length);try{selected.receive(reply);}catch(SocketTimeoutException wait){continue;}if(++frames>128)throw new IOException();NodeUpdateCodec.Frame frame;try{frame=NodeUpdateCodec.frame(bytes,reply.getLength());}catch(Exception malformed){continue;}if(frame.message.kind!='R'||!NodeUpdateCodec.same(message,frame.message)||!frame.verify(node.publicKey))continue;if(expectedRun!=null&&!expectedRun.equals(frame.message.run))throw new SecurityException("Node boot changed");check();if(clock.getAsLong()-began>=8000||reservation!=null&&!reservation.fresh(clock.getAsLong()))throw new SocketTimeoutException();return new Reading(frame.message,began);}throw new SocketTimeoutException();}
 static final class Chunk {final int begin,end;final byte[] packet;long sent;int attempts;Chunk(int begin,int end,byte[] packet){this.begin=begin;this.end=end;this.packet=packet;}}
 void upload(File image,NodeReleaseManifest release,Reading original,KeyPair ephemeral,LongConsumer progress)throws Exception{
  NodeUpdateCodec.Message start=NodeUpdateCodec.start(original.message,ephemeral,release);NodeUpdateCodec.Keys keys=NodeUpdateCodec.derive(ephemeral,original.message,start);try{
   Reading admitted;try{admitted=exchange(start,original,original.message.run);}catch(SocketTimeoutException unknown){admitted=query(original.message.run);}
   if(!admitted.message.session.equals(start.session)||!admitted.message.artifact.equals(release.id)||admitted.message.state!=1||admitted.message.contiguous!=0)throw new SecurityException("Node did not accept the selected update");
   DatagramSocket selected=socket();NodeUpdateCodec.Replay replay=new NodeUpdateCodec.Replay();long counter=0,lastProgress=clock.getAsLong();int acknowledged=0,next=0;LinkedList<Chunk> pending=new LinkedList<>();try(RandomAccessFile input=new RandomAccessFile(image,"r")){
    while(acknowledged<release.imageBytes){check();while(pending.size()<4&&next<release.imageBytes){int n=Math.min(1024,release.imageBytes-next);byte[] data=new byte[n];input.seek(next);input.readFully(data);byte[] encrypted=NodeUpdateCodec.encrypt(node.id,start.session,++counter,NodeUpdateCodec.plaintext(1,0,0,next,data),keys.send,keys.sendPrefix);pending.add(new Chunk(next,next+n,encrypted));next+=n;}
     long now=clock.getAsLong();if(now<lastProgress||now-lastProgress>=30000)throw new SocketTimeoutException();for(Chunk chunk:pending)if(chunk.attempts==0||now-chunk.sent>=1200){check();if(chunk.attempts++>=12)throw new SocketTimeoutException();selected.send(new DatagramPacket(chunk.packet,chunk.packet.length));chunk.sent=now;}
     byte[] incoming=new byte[NodeUpdateCodec.MAX_PACKET+1];DatagramPacket reply=new DatagramPacket(incoming,incoming.length);try{selected.receive(reply);}catch(SocketTimeoutException waiting){continue;}NodeUpdateCodec.Plain ack;try{ack=NodeUpdateCodec.decrypt(incoming,reply.getLength(),node.id,start.session,keys.receive,keys.receivePrefix,replay);}catch(Exception unauthenticated){continue;}
     check();if(ack.kind!=2||ack.error!=0||ack.state==6||ack.offset<acknowledged||ack.offset>next||ack.offset!=release.imageBytes&&ack.offset%1024!=0)throw new SecurityException("Invalid authenticated update acknowledgement");if(ack.offset>acknowledged){acknowledged=ack.offset;lastProgress=clock.getAsLong();while(!pending.isEmpty()&&pending.getFirst().end<=acknowledged)pending.removeFirst();progress.accept(acknowledged);}
    }
   }
   byte[] end=NodeUpdateCodec.encrypt(node.id,start.session,++counter,NodeUpdateCodec.plaintext(3,0,0,release.imageBytes,new byte[0]),keys.send,keys.sendPrefix);long began=clock.getAsLong(),last=Long.MIN_VALUE;while(live()&&clock.getAsLong()-began<12000){long now=clock.getAsLong();if(last==Long.MIN_VALUE||now-last>=1200){check();selected.send(new DatagramPacket(end,end.length));last=now;}byte[] bytes=new byte[NodeUpdateCodec.MAX_PACKET+1];DatagramPacket response=new DatagramPacket(bytes,bytes.length);try{selected.receive(response);}catch(SocketTimeoutException waiting){continue;}NodeUpdateCodec.Plain ack;try{ack=NodeUpdateCodec.decrypt(bytes,response.getLength(),node.id,start.session,keys.receive,keys.receivePrefix,replay);}catch(Exception unauthenticated){continue;}check();if(ack.kind==2&&ack.error==0&&ack.state==2&&ack.offset==release.imageBytes)return;if(ack.error!=0||ack.state==6)throw new IOException("Node could not verify the update");}throw new SocketTimeoutException();
  }finally{keys.clear();}
 }
 void reopen(){DatagramSocket owned=socket.getAndSet(null);if(owned!=null)owned.close();}public void close(){closed.set(true);reopen();}
}
